import React, { useState } from 'react';
import { Button, Input, Space, Table, Tag, Select, Image, Typography, Badge, Slider, DatePicker } from 'antd';
import { SearchOutlined, PlusOutlined, EditOutlined, WarningOutlined } from '@ant-design/icons';
import type { ColumnsType } from 'antd/es/table';
import { usePage, Link } from '@inertiajs/react';
import AppLayout from '@/layouts/app-layout';
import dayjs from 'dayjs';
import DeleteProduct from '@/pages/Products/DeleteProduct';
import { useTranslation } from 'react-i18next';

const { Text } = Typography;
const { RangePicker } = DatePicker;

interface ProductType {
    key: string;
    id: string;
    name: string;
    price: number;
    barcode: string;
    category: string;
    stock: number;
    image_path?: string;
    expiring_soon?: boolean;
    expired?: boolean;
    days_until_expiration?: number;
    low_stock?: boolean;
}

interface CategoryType {
    id: number;
    name: string;
}

interface BreadCrumb {
    title: string;
    href: string;
}

const formatIQD = (price: number): string => {
    return new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'IQD',
        minimumFractionDigits: 0,
        maximumFractionDigits: 0,
    })
        .format(price)
        .replace('IQD', 'IQD ');
};

const ProductsPage: React.FC = () => {
    const { t } = useTranslation();

    const { products = [], categories = [] } = usePage().props as unknown as {
        products: ProductType[];
        categories: CategoryType[];
    };

    const [searchText, setSearchText] = useState('');
    const [searchCategory, setSearchCategory] = useState<string | null>(null);
    const [stockRange, setStockRange] = useState<[number, number] | null>(null);
    const [expirationRange, setExpirationRange] = useState<[dayjs.Dayjs, dayjs.Dayjs] | null>(null);
    const [showLowStock, setShowLowStock] = useState<boolean | null>(null);
    const [expirationStatus, setExpirationStatus] = useState<string | boolean | null>(null);

    const getMaxStock = () => {
        if (products.length === 0) return 100;
        return Math.max(...products.map(product => product.stock));
    };

    const filteredProducts = products.filter(product => {
        // Text search filter
        const matchesText = searchText === '' ||
            product.name.toLowerCase().includes(searchText.toLowerCase()) ||
            product.barcode.includes(searchText);

        // Category filter
        const matchesCategory = !searchCategory || product.category === searchCategory;

        // Stock range filter
        const matchesStockRange = !stockRange ||
            (product.stock >= stockRange[0] && product.stock <= stockRange[1]);

        // Low stock filter
        const matchesLowStock = showLowStock === null ||
            (showLowStock === true ? product.low_stock : !product.low_stock);

        // Expiration status filter
        const matchesExpirationStatus = expirationStatus === null ||
            (expirationStatus === "expired" ? product.expired :
             expirationStatus === true ? product.expiring_soon && !product.expired :
             !product.expiring_soon && !product.expired);

        // Expiration date range filter
        let matchesExpirationRange = true;
        if (expirationRange && product.days_until_expiration !== undefined) {
            const today = dayjs();
            const productExpirationDate = today.add(product.days_until_expiration, 'day');
            matchesExpirationRange = productExpirationDate.isAfter(expirationRange[0]) &&
                                    productExpirationDate.isBefore(expirationRange[1]);
        }

        return matchesText && matchesCategory && matchesStockRange &&
               matchesLowStock && matchesExpirationStatus && matchesExpirationRange;
    });

    const columns: ColumnsType<ProductType> = [
        // {
        //     title: t('products.image'),
        //     key: 'image',
        //     width: 80,
        //     render: (_, record) => (
        //         record.image_path ? (
        //             <Image
        //                 src={`/storage/${record.image_path}`}
        //                 alt={record.name}
        //                 width={50}
        //                 height={50}
        //                 style={{ objectFit: 'cover' }}
        //                 fallback="data:image/png;base64,"
        //             />
        //         ) : (
        //             <div className="w-[50px] h-[50px] bg-gray-100 flex items-center justify-center">
        //                 <Text type="secondary">No Image</Text>
        //             </div>
        //         )
        //     ),
        // },
        {
            title: t('products.name'),
            dataIndex: 'name',
            key: 'name',
            render: (text, record) => <Link href={route('product.edit', record.id)}>{text}</Link>,
        },
        {
            title: t('products.price'),
            dataIndex: 'price',
            key: 'price',
            render: (price) => formatIQD(price),
            sorter: (a, b) => a.price - b.price,
        },
        {
            title: t('products.category'),
            dataIndex: 'category',
            key: 'category',
            render: (category) => (
                <Tag color={category === 'Electronics' ? 'blue' : category === 'Kitchen' ? 'green' : 'orange'}>
                    {category}
                </Tag>
            ),
            filters: categories.map(category => ({ text: category.name, value: category.name })),
            onFilter: (value, record) => record.category === value,
        },
        {
            title: t('products.stock'),
            dataIndex: 'stock',
            key: 'stock',
            render: (stock, record) => (
                <Space>
                    {record.low_stock ? (
                        <Badge status="warning" text={`${stock} (Low)`} />
                    ) : (
                        stock
                    )}
                </Space>
            ),
            sorter: (a, b) => a.stock - b.stock,
        },
        {
            title: t('products.barcode'),
            dataIndex: 'barcode',
            key: 'barcode',
        },
   {
       title: t('products.expiration'),
       key: 'expiration',
       render: (_, record) => {
           if (record.expired) {
               return <Badge status="error" text={t('dashboard.products.expired')} />;
           } else if (record.days_until_expiration !== undefined) {
               if (record.days_until_expiration > 30) {
                   const months = Math.floor(record.days_until_expiration / 30);
                   const remainingDays = record.days_until_expiration % 30;

                   return (
                       <Text>
                           {months} مانگ
                           {remainingDays > 0 ? ` ${remainingDays} رۆژ ` : ''}
                       </Text>
                   );
               } else if (record.days_until_expiration <= 14) {
                   return (
                       <Text type="danger" style={{ fontWeight: 'bold' }}>
                           <WarningOutlined style={{ marginRight: 4 }} />
                           {record.days_until_expiration}  رۆژ
                       </Text>
                   );
               } else {
                   return <Text>{record.days_until_expiration} رۆژ </Text>;
               }
           } else {
               return <Text type="secondary">بێ بەروارە</Text>;
           }
       },
       sorter: (a, b) => {
           const daysA = a.days_until_expiration ?? Infinity;
           const daysB = b.days_until_expiration ?? Infinity;
           return daysA - daysB;
       },
   },
        {
            title: t('common.action'),
            key: 'action',
            render: (_, record) => (
                <Space size="middle">
                    <Link href={route('product.edit', record.id)}>
                        <Button type="text" icon={<EditOutlined />}>{t('products.edit.title')}</Button>
                    </Link>
                    <DeleteProduct product={record} />
                </Space>
            ),
        },
    ];

    const breadcrumbs: BreadCrumb[] = [
        {title: t('dashboard.title'), href: route('dashboard')},
        {title: t('products.title'), href: route('product.index')},
    ];

    const resetFilters = () => {
        setSearchText('');
        setSearchCategory(null);
        setStockRange(null);
        setExpirationRange(null);
        setShowLowStock(null);
        setExpirationStatus(null);
    };

    return (
        <AppLayout breadcrumbs={breadcrumbs}>
            <div className="products-dashboard">
                <div className="mb-6 flex items-center justify-between">
                    <h1 className="text-2xl font-bold">{t('products.management')}</h1>
                    <Link href={route('product.create')}>
                        <Button type="primary" icon={<PlusOutlined />}>
                            {t('products.addProduct')}
                        </Button>
                    </Link>
                </div>

                <div className="mb-6 p-4 bg-gray-50 border border-gray-200 rounded-md">
                    <div className="mb-3 font-semibold">{t('products.filters')}</div>
                    <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-4">
                        {/* Text search */}
                        <div>
                            <div className="mb-1 text-sm text-gray-600">{t('products.search')}</div>
                            <Input
                                placeholder={t('products.searchPlaceholder')}
                                prefix={<SearchOutlined />}
                                value={searchText}
                                onChange={(e) => setSearchText(e.target.value)}
                            />
                        </div>

                        {/* Category filter */}
                        <div>
                            <div className="mb-1 text-sm text-gray-600">{t('products.category')}</div>
                            <Select
                                placeholder={t('products.filterByCategory')}
                                style={{ width: '100%' }}
                                allowClear
                                value={searchCategory}
                                onChange={(value) => setSearchCategory(value)}
                            >
                                {categories.map((category) => (
                                    <Select.Option key={category.id} value={category.name}>
                                        {category.name}
                                    </Select.Option>
                                ))}
                            </Select>
                        </div>

                        {/* Stock range filter */}
                        <div>
                            <div className="mb-1 text-sm text-gray-600">{t('products.stockRange')}</div>
                            <Slider
                                range
                                min={0}
                                max={getMaxStock()}
                                value={stockRange || [0, getMaxStock()]}
                                onChange={(value) => setStockRange(value as [number, number])}
                            />
                        </div>

                        {/* Low stock filter */}
                        <div>
                            <div className="mb-1 text-sm text-gray-600">{t('products.stockStatus')}</div>
                            <Select
                                placeholder={t('products.stockStatus')}
                                style={{ width: '100%' }}
                                allowClear
                                value={showLowStock}
                                onChange={(value) => setShowLowStock(value)}
                            >
                                <Select.Option value={true}>{t('products.lowStock')}</Select.Option>
                                <Select.Option value={false}>{t('products.normalStock')}</Select.Option>
                            </Select>
                        </div>

                        {/* Expiration range */}
                        <div>
                            <div className="mb-1 text-sm text-gray-600">{t('products.expirationDate')}</div>
                            <RangePicker
                                style={{ width: '100%' }}
                                value={expirationRange}
                                onChange={(dates) => setExpirationRange(dates as [dayjs.Dayjs, dayjs.Dayjs])}
                            />
                        </div>

                        {/* Expiration status filter */}
                        <div>
                            <div className="mb-1 text-sm text-gray-600">{t('products.expirationStatus')}</div>
                            <Select
                                placeholder={t('products.expirationStatus')}
                                style={{ width: '100%' }}
                                allowClear
                                value={expirationStatus}
                                onChange={(value) => setExpirationStatus(value)}
                            >
                                <Select.Option value="expired">{t('products.expired')}</Select.Option>
                                <Select.Option value={true}>{t('products.expiringSoon')}</Select.Option>
                                <Select.Option value={false}>{t('products.notExpiringSoon')}</Select.Option>
                            </Select>
                        </div>

                        {/* Reset button */}
                        <div className="flex items-end">
                            <Button onClick={resetFilters}>
                                {t('products.resetFilters')}
                            </Button>
                        </div>
                    </div>
                </div>

                {/* Product counts summary */}
                <div className="mb-4 flex flex-wrap gap-4">
                    <Tag color="blue">{t('products.total')}: {products.length}</Tag>
                    <Tag color="orange">{t('products.lowStock')}: {products.filter(p => p.low_stock).length}</Tag>
                    <Tag color="red">{t('products.expiringSoon')}: {products.filter(p => p.expiring_soon).length}</Tag>
                    <Tag color="black">{t('products.expired')}: {products.filter(p => p.expired).length}</Tag>
                    <Tag color="purple">{t('products.filtered')}: {filteredProducts.length}</Tag>
                </div>

                <Table
                    columns={columns}
                    dataSource={filteredProducts}
                    rowKey="key"
                    pagination={{ pageSize: 5 }}
                    bordered
                />
            </div>
        </AppLayout>
    );
};

export default ProductsPage;
